// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 unused) public {
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount < address(this).balance);

        // Deploy a helper contract that always reverts on receiving ETH
        Reverter reverter = new Reverter();

        // Fund the reverter with a deposit from its own address so it has credit
        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.deposit{value: depositAmount}();

        // Record contract balance before withdrawal
        uint256 contractBalanceBefore = address(c).balance;
        uint256 creditBefore = c.credit(address(reverter));

        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a failing withdrawal, the correct contract must have reverted (ok=false)
        // AND state must be unchanged. The buggy version will not revert (ok=true)
        // and will have incorrectly updated balance and zeroed credit.
        // General rule: (revert || (balance unchanged && credit unchanged))
        bool stateUnchanged = (
            address(c).balance == contractBalanceBefore &&
            c.credit(address(reverter)) == creditBefore
        );
        assertTrue(!ok || stateUnchanged);
    }
}

contract Reverter {
    fallback() external payable {
        revert("ETH transfer failed");
    }
}

