pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(actor != address(this) && actor != address(c) && actor.code.length == 0);
        vm.assume(depositAmount > 0 && withdrawAmount <= depositAmount);

        // Deploy a helper that rejects ETH
        Reverter reverter = new Reverter();
        address recipient = address(reverter);

        // 1. Deposit as actor
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // 2. Deposit as reverter to create a credit that will trigger a failed withdrawal
        vm.deal(recipient, depositAmount);
        vm.prank(recipient);
        c.deposit{value: depositAmount}();

        // 3. Trigger withdrawAll on reverter (which will fail on ETH transfer)
        vm.prank(recipient);
        c.withdrawAll();

        // The invariant: contract's balance must equal sum of all remaining credits
        // After failed withdrawal, the credit for recipient should NOT be zero in reference (it reverts),
        // but WILL be zero in mutant (state changes persist).
        // Since we can't directly read credit (it's private), we check: balance == address(c).balance
        // But that's trivially maintained by the code. Instead, we check that balance >= the known credits.
        // Better: actor withdraws their credit - if contract balance is insufficient, it reveals the inconsistency.
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();

        // After actor's withdrawal, contract balance should be zero if everything is consistent
        // In reference: recipient's credit remains, so balance = recipient's credit (which = depositAmount)
        // In mutant: recipient's credit was zeroed, so balance = 0
        assertTrue(address(c).balance == 0 || address(c).balance == depositAmount);
    }
}

