pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, address caller) public {
        // Admissible domain: keep amounts reasonable and avoid precompile/EoA collisions
        vm.assume(depositAmount > 0 && depositAmount < 1 ether);
        vm.assume(caller != address(0) && caller.code.length == 0);

        // Deploy a failing callee that reverts in receive
        Reverter reverter = new Reverter();
        // Fund the caller and the failing callee
        vm.deal(caller, 1 ether);
        vm.deal(reverter, 0);

        // Deposit
        vm.prank(caller);
        c.deposit{value: depositAmount}();

        uint creditBefore = c.credit(caller);

        // Attempt withdrawal from the reverter address (simulating a failed ETH transfer)
        vm.prank(reverter);
        c.withdrawAll();

        // After the call, inspect credit of the reverter address.
        // Reference: reverts, credit remains unchanged (0). Mutant: clears credit to 0 but doesn't revert.
        uint creditAfter = c.credit(reverter);

        assertTrue(creditAfter == 0);
    }
}

