        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);

        // Deposit funds as the actor
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Record pre-conditions
        uint256 balanceBefore = address(c).balance;
        uint256 totalCreditBefore = c.credit(actor);

        // Perform the withdrawAll call
        vm.prank(actor);
        c.withdrawAll();

        // Post-conditions
        uint256 balanceAfter = address(c).balance;
        uint256 totalCreditAfter = c.credit(actor);

        // General invariant: contract ETH balance must always decrease by exactly the amount of credit cleared.
        // The reference version sends ETH, so balance Delta equals credit Delta.
        // The buggy version clears credit without sending ETH, so balance Delta (0) != credit Delta (>0).
        assertTrue(balanceBefore - balanceAfter == totalCreditBefore - totalCreditAfter);
    }
}

