pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 times) public {
        vm.assume(user != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        // Bound times to a manageable range to avoid infinite loop, but wide enough for bug manifestation
        times = bound(times, 0, 5);

        // Fund the user and deposit multiple times if needed (each deposit adds credit and balance)
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Record state after deposit
        uint256 initialCredit = c.credit(user);
        uint256 initialBalance = c.balance();
        uint256 initialContractBalance = address(c).balance;

        // Call withdrawAll multiple times (bug: credit isn't cleared, so later calls succeed with same credit)
        for (uint256 i = 0; i < times; i++) {
            vm.prank(user);
            c.withdrawAll();
        }

        // After all calls, contract balance should be exactly initialBalance - initialCredit
        // (credit cleared once in reference; but bug deducts balance each time without clearing credit)
        uint256 finalContractBalance = address(c).balance;
        // Invariant: final balance >= initialBalance - (times * initialCredit) if bug allowed multiple withdrawals?
        // Actually, reference deducts once, bug deducts up to initialCredit each time (if balance allows).
        // The invariant: finalContractBalance == initialBalance - initialCredit
        // Bug: if times > 1 and balance was sufficient, contract balance is lower than expected.
        // Since credit is never zeroed, reference only allows one withdrawal; bug allows repeated ones.
        // Assert: finalContractBalance == initialBalance - initialCredit
        // If times=0, no withdrawals; times=1, correct; times>1, bug underflows contract balance.
        assertTrue(finalContractBalance == initialBalance - initialCredit);
    }
}

