pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address user) public {
        // Restrict to non-zero amount and user that is not the contract itself nor a precompile
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(user != address(0) && user != address(c) && user.code.length == 0);

        // Record initial contract balance
        uint256 initialBalance = address(c).balance;

        // User deposits
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();

        // User withdraws once
        vm.prank(user);
        c.withdrawAll();

        uint256 balanceAfterOneWithdraw = address(c).balance;
        // Initial balance should have decreased by exactly the deposited amount
        // We are not asserting this intermediate invariant; it is just part of the setup.

        // User withdraws a second time; this may succeed or revert depending on implementation
        bool secondCallReverted;
        vm.prank(user);
        try c.withdrawAll() {
            secondCallReverted = false;
        } catch {
            secondCallReverted = true;
        }

        uint256 balanceAfterSecondAttempt = address(c).balance;

        // In the reference implementation, the second call does nothing (credit=0) and balance stays unchanged.
        // In the buggy implementation, the second call transfers the same credit again, draining extra balance.
        // The invariant: balanceAfterSecondAttempt >= initialBalance - amount
        // The reference always satisfies this; the bug can violate it when the second withdrawAll succeeds and transfers amount again.
        assertTrue(balanceAfterSecondAttempt >= initialBalance - amount);
    }
}

