        amount = bound(amount, 1, type(uint128).max);

        // Ensure the caller has funds to deposit
        vm.deal(caller, amount);

        // Deposit as the caller
        vm.prank(caller);
        c.deposit{value: amount}();

        // Withdraw all as the caller
        vm.prank(caller);
        c.withdrawAll();

        // After full withdrawal, the caller's credit must be 0 in the reference contract;
        // the mutant leaves it as 1, so the invariant that total credits == balance is broken.
        // We obtain balance via the auto-generated getter for the public state variable 'balance'.
        // We cannot read credit[caller] directly (it's private), so we assert on the sum of credits
        // by performing an additional deposit/withdrawal cycle that would expose the discrepancy.
        // However, a simpler universal rule: after a single deposit + withdrawAll by the same caller,
        // the contract's balance must be 0. The mutant leaves balance unchanged but credit becomes 1,
        // so a subsequent deposit by another party will cause balance to exceed total withdrawable credits.
        // Directly observable: after the full withdrawal, balance should be 0.
        uint256 bal = c.balance();
        assertTrue(bal == 0);
    }
}

